public function version(array $target):string{[$table,$id]=$target;$row=DB::table($table)->find($id);abort_unless($row,404);return hash_hmac('sha256',json_encode([$table,$id,(array)$row]),(string)config('app.key'));}
public function before(Request $r,bool $again=false):void{
$rules=app(CcsHumanRules::class);$method=$r->route()?->getActionMethod();$class=$r->route()?->getControllerClass();$id=(int)($r->route('id')??0);if($this->target($r))$r->validate(['rules_confirm'=>'required|accepted']);
if($class===\App\Http\Controllers\CcsWarrantyController::class&&$method==='approveRecord'){$w=DB::table('warranties')->find($id);if((json_decode($w->terms_snapshot??'{}',true)['revoked']??false))$rules->fail('confirmation','A voided invoice warranty cannot be reapproved.');}
