if(in_array($method,['saveCustomer','updateCustomer'],true))$rules->customer($r,$method==='updateCustomer'?$id:null);
if(in_array($method,['saveCustomer','saveVehicle'],true))$rules->vehicle($r,$again);
if(in_array($method,['saveJob','updateJob','updateJobDetails'],true)){
$name=trim((string)$r->input('technician_name'));$priorName=$id?DB::table('repair_jobs')->where('id',$id)->value('technician_name'):null;if($name!==''&&$name!==$priorName&&DB::table('users')->where('name',$name)->where('ccs_active',true)->where('ccs_role','technician')->count()!==1)$rules->fail('technician_name','Choose one active technician. If two technicians share a name, give each a distinct display name.');
$job=$id?DB::table('repair_jobs')->find($id):null;$vehicleId=$job->vehicle_id??(int)$r->input('vehicle_id');$vehicle=DB::table('vehicles')->where('id',$vehicleId)->whereNull('deleted_at')->first();$baseline=max((int)($vehicle->current_mileage_km??0),(int)DB::table('repair_jobs')->where('vehicle_id',$vehicleId)->whereNull('deleted_at')->when($id,fn($q)=>$q->where('id','!=',$id))->max('mileage_at_service_km'));if($vehicle&&$r->filled('mileage_at_service_km')&&(int)$r->input('mileage_at_service_km')<$baseline){$r->validate(['rules_reason'=>'required|string|min:5|max:500']);$approval=$rules->approve($r,'mileage_correction',['vehicle_id'=>$vehicleId,'old'=>$baseline,'new'=>$r->input('mileage_at_service_km'),'reason'=>$r->input('rules_reason')],!$again);$r->attributes->set('rules_mileage_approval',$approval);}
if($method==='saveJob'&&DB::table('repair_jobs')->where('vehicle_id',$vehicleId)->whereNull('deleted_at')->whereNotIn('status',['completed','closed','delivered'])->exists()&&!$r->boolean('rules_active_job'))$rules->fail('vehicle_id','This vehicle already has an active job. Review it, then confirm Create another active job if needed.');
