}
if($method==='updateInvoiceItemDetails'){$line=DB::table('invoice_items')->find($id);if($line&&DB::table('invoices')->where('id',$line->invoice_id)->value('status')!=='draft')$rules->fail('rules','Finalized invoice item details are locked. Use a documented correction instead.');}
if($method==='createInvoice'){$r->validate(['description'=>'required|array|min:1|max:20','discount'=>'nullable|numeric|min:0|decimal:0,2']);foreach($r->input('description',[]) as $desc)if(trim((string)$desc)==='')$rules->fail('description','An invoice item description cannot be empty.');$data=['job_id'=>(int)$r->input('repair_job_id'),'description'=>$r->input('description'),'quantity'=>$r->input('quantity'),'unit_price'=>$r->input('unit_price'),'inventory_item_id'=>$r->input('inventory_item_id',[]),'stock_unit_id'=>$r->input('stock_unit_id',[]),'serial'=>$r->input('manual_serial',[]),'discount'=>number_format((float)$r->input('discount',0),2,'.','')];if((float)$r->input('discount',0)>0){$approval=$rules->approve($r,'discount',$data,!$again);$r->attributes->set('rules_discount_approval',$approval);if(!$approval)$r->attributes->set('rules_discount_authorized_by',$r->user()->id);}if($r->filled('credit_nic')){$nic=$rules->nic($r->input('credit_nic'));$cid=DB::table('repair_jobs as j')->join('vehicles as v','v.id','=','j.vehicle_id')->where('j.id',(int)$r->input('repair_job_id'))->value('v.customer_id');foreach(DB::table('customers')->whereNull('deleted_at')->where('id','!=',$cid)->whereNotNull('nic')->get(['id','nic']) as $c){try{$other=$rules->nic($c->nic);}catch(\Illuminate\Validation\ValidationException){continue;}if($rules->nicKey($other)===$rules->nicKey($nic))$rules->fail('credit_nic','NIC belongs to another customer #'.$c->id.'. Review the selected customer.');}$r->merge(['credit_nic'=>$nic]);}if($r->filled('credit_phone'))$r->merge(['credit_phone'=>$rules->phone($r->input('credit_phone'))]);}
}
if($class===\App\Http\Controllers\CcsStockController::class){if(in_array($method,['create','update'],true))foreach(['sku','name'] as $field)if($r->has($field)&&trim((string)$r->input($field))==='')$rules->fail($field,'Part code and part name cannot be empty.');if($method==='create'){if($r->filled('serials')&&$r->filled('quantity')){$count=count(array_filter(array_map('trim',preg_split('/\R/',(string)$r->input('serials')))));if((int)$r->input('quantity')!==$count)$rules->fail('quantity','Opening quantity must match the number of serials entered.');}if(!$r->boolean('has_serial')||$r->boolean('serial_on_sale'))$r->validate(['quantity'=>'required|integer|min:0|max:10000']);$r->validate(['selling_price_lkr'=>'required|numeric|min:0|decimal:0,2']);}if(in_array($method,['create','update'],true)&&$r->filled('selling_price_lkr')&&((float)$r->input('selling_price_lkr')===0||((float)$r->input('selling_price_lkr')<(float)$r->input('purchase_price_lkr',$id?DB::table('inventory_items')->where('id',$id)->value('purchase_price_lkr'):0)))&&!$r->boolean('rules_price_confirm'))$rules->fail('selling_price_lkr','Zero price or selling below cost. Review and tick Price warning confirmed.');if(in_array($method,['removeUnit','restoreUnit','cancelDraft'],true))$r->validate(['rules_reason'=>'required|string|min:5|max:500']);}
if($class===\App\Http\Controllers\CcsTechnicianController::class&&$method==='update'){$job=DB::table('repair_jobs')->find($id);if($job&&in_array($r->input('status'),['ready','completed'],true)&&$r->input('status')!==$job->status)$r->validate(['rules_completion_check'=>'required|accepted']);if($job&&in_array($r->input('status'),['ready','completed'],true)&&trim((string)$r->input('diagnosis',$job->diagnosis))==='')$rules->fail('diagnosis','Add diagnosis / completion notes before completing the job.');if($job&&in_array($job->status,['ready','completed'],true)&&!in_array($r->input('status'),['ready','completed'],true))$r->validate(['rules_reason'=>'required|string|min:5|max:500']);}
if($class===\App\Http\Controllers\CcsBillingController::class){if($method==='payment'){ $invoice=DB::table('invoices')->find($id);if($invoice){$due=(int)round((float)$invoice->total_lkr*100)-DB::table('payments')->where('invoice_id',$id)->get()->sum(fn($p)=>(int)round((float)$p->amount_lkr*100));if((int)round((float)$r->input('amount_lkr')*100)>$due)$rules->fail('amount_lkr','Later payment cannot exceed the outstanding balance.');}}if($method==='issue'){$inv=DB::table('invoices')->find($id);$p=app(CcsCashierRules::class)->get()['discount'];$authorizedOwner=$inv&&$inv->rules_discount_authorized_by&&$rules->owner(DB::table('users')->find($inv->rules_discount_authorized_by));$needsCheck=$inv&&!$authorizedOwner&&(!$inv->rules_discount_authorized_by||$p['approval']||!$p['allowed']);if($inv&&$inv->status==='draft'&&(float)$inv->discount_lkr>0&&$needsCheck){$approval=$rules->approve($r,'draft_discount',['invoice_id'=>$id,'total'=>$inv->total_lkr,'discount'=>$inv->discount_lkr,'lines'=>DB::table('invoice_items')->where('invoice_id',$id)->orderBy('id')->get()->map(fn($x)=>(array)$x)->all()],!$again);$r->attributes->set('rules_discount_approval',$approval);if(!$approval)$r->attributes->set('rules_discount_authorized_by',$r->user()->id);}}if($method==='issue'&&!DB::table('invoice_items')->where('invoice_id',$id)->exists())$rules->fail('confirmation','Cannot finalize an empty invoice.');}
if($class===\App\Http\Controllers\CcsClaimController::class&&in_array($method,['decision','job'],true)){$wid=DB::table('warranty_claims')->where('id',$id)->value('warranty_id');$terms=json_decode(DB::table('warranties')->where('id',$wid)->value('terms_snapshot')??'{}',true);if(($terms['revoked']??false)&&$r->input('status')!=='rejected')$rules->fail('status','The source invoice is voided. This warranty cannot authorize a claim.');}
if($class===\App\Http\Controllers\CcsClaimController::class&&$r->filled('warranty_id')){$w=DB::table('warranties')->find((int)$r->input('warranty_id'));$terms=$w?json_decode($w->terms_snapshot,true):[];if($terms['revoked']??false)$rules->fail('warranty_id','This warranty was revoked because the invoice was voided.');if($w&&$w->expires_on&&$w->expires_on<today()->toDateString()&&!$r->boolean('rules_expired_claim'))$rules->fail('warranty_id','Warranty time limit has elapsed. Confirm the warning to register for Owner review; this does not approve coverage.');}
}
public function consume(Request $r):void{foreach($r->attributes->get('rules_confirmed_actions',[]) as $kind=>$details)app(CcsAdministration::class)->audit($r->user()->id,'cashier_action_confirmed','rules',null,['kind'=>$kind,'details'=>$details,'confirmed'=>true]);if($r->route()?->getActionMethod()==='issue'){$approval=$r->attributes->get('rules_discount_approval');$by=$r->attributes->get('rules_discount_authorized_by')??($approval?DB::table('ccs_rule_approvals')->where('id',$approval)->value('decided_by'):(app(CcsHumanRules::class)->owner($r->user())?$r->user()->id:null));if($by)DB::table('invoices')->where('id',(int)$r->route('id'))->update(['rules_discount_authorized_by'=>$by]);}foreach(['rules_plate_approval','rules_discount_approval','rules_mileage_approval'] as $key)app(CcsHumanRules::class)->consume($r->attributes->get($key),(int)$r->user()->id);}
}
